-- Enact360 CRM - normalized PostgreSQL schema
-- Generated by gen_schema.py. Idempotent: safe to re-run.

BEGIN;

-- Applied migration versions.
CREATE TABLE IF NOT EXISTS schema_migrations (
  version TEXT NOT NULL,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  description TEXT,
  PRIMARY KEY (version)
);

-- Singleton/global scalars (state_initialized, updated_at, payroll org masters, ...).
CREATE TABLE IF NOT EXISTS app_settings (
  key TEXT NOT NULL,
  value JSONB,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (key)
);

-- Running document-number counters (leads, invoices:Tax, ...).
CREATE TABLE IF NOT EXISTS document_counters (
  counter_key TEXT NOT NULL,
  value BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (counter_key)
);

-- Company/supplier profile (single row).
CREATE TABLE IF NOT EXISTS company_profile (
  source TEXT NOT NULL,
  legacy_id INTEGER,
  name TEXT,
  legal_name TEXT,
  gstin TEXT,
  pan TEXT,
  cin TEXT,
  state TEXT,
  state_code TEXT,
  city TEXT,
  pincode TEXT,
  address TEXT,
  email TEXT,
  phone TEXT,
  website TEXT,
  logo_url TEXT,
  bank_name TEXT,
  account_number TEXT,
  ifsc_code TEXT,
  branch TEXT,
  bank_details JSONB,
  bank_accounts JSONB,
  ui_font_size TEXT,
  ui_theme TEXT,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (source)
);

-- Outlook app registration config (single row).
CREATE TABLE IF NOT EXISTS outlook_app_config (
  id INTEGER NOT NULL,
  client_id TEXT,
  display_name TEXT,
  object_id TEXT,
  tenant_id TEXT,
  redirect_uris TEXT,
  managed_application TEXT,
  smtp_host TEXT,
  smtp_port INTEGER,
  supported_account_types TEXT,
  state TEXT,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id)
);

-- Email-notification config (single row).
CREATE TABLE IF NOT EXISTS outlook_email_config (
  id INTEGER NOT NULL,
  enabled BOOLEAN,
  outlook_email TEXT,
  cc_emails TEXT,
  sender_display_name TEXT,
  server_type TEXT,
  smtp_host TEXT,
  smtp_port INTEGER,
  use_start_tls BOOLEAN,
  app_display_name TEXT,
  client_id TEXT,
  object_id TEXT,
  tenant_id TEXT,
  supported_account_types TEXT,
  redirect_uri_config TEXT,
  managed_application TEXT,
  app_state TEXT,
  notify_on_lead BOOLEAN,
  notify_on_opportunity BOOLEAN,
  notify_on_order BOOLEAN,
  notify_on_invoice BOOLEAN,
  notify_on_payment BOOLEAN,
  notify_on_milestone BOOLEAN,
  notify_on_support BOOLEAN,
  notify_on_activity BOOLEAN,
  notify_on_user BOOLEAN,
  auto_include_assigned_owner BOOLEAN,
  updated_at TIMESTAMPTZ,
  PRIMARY KEY (id)
);

-- Application users / employees.
CREATE TABLE IF NOT EXISTS users (
  id TEXT NOT NULL,
  name TEXT,
  username TEXT,
  email TEXT,
