  gender TEXT,
  blood_group TEXT,
  marital_status TEXT,
  alternate_phone TEXT,
  personal_email TEXT,
  current_address TEXT,
  permanent_address TEXT,
  city TEXT,
  state TEXT,
  pin_code TEXT,
  bank_name TEXT,
